// Some portions generated by Co-Pilot
package org.eclipse.rdf4j.sail.lmdb;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertThrows;
import static org.junit.jupiter.api.Assertions.assertTrue;

import java.io.IOException;
import java.nio.file.Files;
import java.nio.file.Path;
import java.util.ArrayList;
import java.util.List;

import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.io.TempDir;

class LmdbBackupDirectoryDurabilityTest {

	@Test
	void forcesEveryAncestorBeforeAcknowledgingNestedRoots(@TempDir Path directory) throws Exception {
		Path journals = directory.resolve("new-parent/backups/txlog");
		List<Path> forced = new ArrayList<>();
		LmdbBackupServiceImpl.createDurableDirectories(journals, path -> {
			assertTrue(Files.isDirectory(path));
			forced.add(path);
		});
		List<Path> expected = new ArrayList<>();
		for (Path path = journals.toAbsolutePath(); path != null; path = path.getParent()) {
			expected.add(path);
		}
		assertEquals(expected, forced);
		forced.clear();
		LmdbBackupServiceImpl.createDurableDirectories(journals, forced::add);
		assertEquals(expected, forced, "a retry must also force pre-existing but possibly unflushed ancestors");
	}

	@Test
	void propagatesAncestorForceFailure(@TempDir Path directory) {
		Path root = directory.resolve("backups");
		IOException failure = assertThrows(IOException.class,
				() -> LmdbBackupServiceImpl.createDurableDirectories(root, path -> {
					if (path.equals(directory)) {
						throw new IOException("parent durability failure");
					}
				}));
		assertEquals("parent durability failure", failure.getMessage());
	}
}
